/**
 * A text file based implementation of a {@link ViolationStore}.<br>
 * This {@link ViolationStore} will store the violations of every single {@link FreezingArchRule} in a dedicated file.<br>
 * It will keep an index of all stored rules as well as a mapping to the individual rule violation files in the same folder.
 * <p>
 * The store can be configured through the following properties:
 * <pre><code>
 * default.path=...               # string: the path of the folder where violation files will be stored
 * default.allowStoreCreation=... # boolean: whether to allow creating a new index file
 * default.allowStoreUpdate=...   # boolean: whether to allow updating any store file
 * default.fileNames=random       # random, description, or a RuleViolationFileNameStrategy class
 * default.integrity=ignore       # ignore, repair, or fail
 * </code></pre>
 */
@PublicAPI(usage = ACCESS)
public final class TextFileBasedViolationStore implements ViolationStore {
    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);

    private static final Pattern UNESCAPED_LINE_BREAK_PATTERN = Pattern.compile("(?<!\\\\)\\n");
    private static final Pattern DESCRIPTION_WORD_PATTERN = Pattern.compile("(?<![A-Za-z0-9])([A-Za-z0-9]{4,120})(?![A-Za-z0-9])");
    private static final Pattern ONLY_LINE_BREAKS_PATTERN = Pattern.compile("(?:\\r\\n|\\r|\\n)*");
    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
    private static final String STORE_PATH_DEFAULT = "archunit_store";
    private static final String STORED_RULES_FILE_NAME = "stored.rules";
    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
    private static final String FILE_NAMES_DEFAULT = "random";
    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
    private static final String INTEGRITY_DEFAULT = "ignore";
    private static final String INTEGRITY_REPAIR = "repair";
    private static final String INTEGRITY_FAIL = "fail";
    private static final String INTEGRITY_IGNORE = "ignore";
    private static final String FILE_NAMES_RANDOM = "random";
    private static final String FILE_NAMES_DESCRIPTION = "description";

    /*
     * The object in this map is both the in-process lock and the in-memory view of
     * the index. This is deliberately keyed by the canonical index path, so a
     * folder reached through a link shares the same lock.
     */
    private static final ConcurrentHashMap<String, FileSyncedProperties> STORED_RULES_BY_PATH = new ConcurrentHashMap<>();

    private final RuleViolationFileNameStrategy constructorStrategy;
    private final boolean strategyWasProvidedToConstructor;

    private RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
    private boolean fileNamesAreDerived;
    private IntegrityMode integrityMode;
    private boolean storeCreationAllowed;
    private boolean storeUpdateAllowed;
    private File storeFolder;
    private File storedRulesFile;
    private FileSyncedProperties storedRules;

    /**
     * Creates a standard store that names new rule violation files randomly.
     */
    public TextFileBasedViolationStore() {
        constructorStrategy = null;
        strategyWasProvidedToConstructor = false;
    }

    /**
     * Creates a store with a custom strategy for rule violation file naming.
     *
     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
     */
    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
        if (ruleViolationFileNameStrategy == null) {
            throw new NullPointerException("ruleViolationFileNameStrategy");
        }
        constructorStrategy = ruleViolationFileNameStrategy;
        strategyWasProvidedToConstructor = true;
    }

    @Override
    public void initialize(Properties properties) {
        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
        integrityMode = integrityMode(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));
        ruleViolationFileNameStrategy = configureFileNameStrategy(properties);

        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "Integrity repair requires %s=true", ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        String path = properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT);
        storeFolder = new File(path);
        storedRulesFile = new File(storeFolder, STORED_RULES_FILE_NAME);
        storedRules = getOrCreateStoredRules(storedRulesFile);

        synchronized (storedRules) {
            prepareFolderAndIndex();
            log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(), storedRulesFile.getAbsolutePath());

            boolean indexExists = Files.exists(storedRulesFile.toPath(), NOFOLLOW_LINKS);
            if (indexExists && !Files.isRegularFile(storedRulesFile.toPath(), NOFOLLOW_LINKS)) {
                throw new StoreInitializationFailedException(String.format(
                        "The stored rules index must be a regular file directly in the store folder: %s", storedRulesFile.getAbsolutePath()));
            }
            if (!indexExists && !storeCreationAllowed) {
                throw new StoreInitializationFailedException(String.format(
                        "Creating new violation store is disabled (enable by configuration %s.%s=true)",
                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
            }

            storedRules.reload(indexExists);
            if (integrityMode == IntegrityMode.IGNORE) {
                if (!indexExists) {
                    storedRules.sync();
                }
                return;
            }

            IntegrityAnalysis analysis = analyzeIntegrity();
            if (integrityMode == IntegrityMode.FAIL) {
                if (analysis.hasProblems()) {
                    throw new StoreInitializationFailedException(analysis.failureReport(storeUpdateAllowed));
                }
                if (!indexExists) {
                    storedRules.sync();
                }
            } else {
                repairIntegrity(analysis);
                if (!indexExists && !storedRules.hasEntries()) {
                    storedRules.sync();
                }
            }
        }
    }

    private void prepareFolderAndIndex() {
        Path folder = storeFolder.toPath();
        try {
            if (!Files.exists(folder, NOFOLLOW_LINKS)) {
                if (!storeCreationAllowed) {
                    throw new StoreInitializationFailedException(String.format(
                            "Creating new violation store is disabled (enable by configuration %s.%s=true)",
                            ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
                }
                Files.createDirectories(folder);
            }
            if (!Files.isDirectory(folder)) {
                throw new StoreInitializationFailedException(String.format(
                        "The violation store path is not a directory: %s", storeFolder.getAbsolutePath()));
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private FileSyncedProperties getOrCreateStoredRules(File file) {
        try {
            String key = file.getCanonicalPath();
            return STORED_RULES_BY_PATH.computeIfAbsent(key, ignored -> new FileSyncedProperties(file));
            return STORED_RULES_BY_PATH.computeIfAbsent(key, ignored -> new FileSyncedProperties(file));
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private IntegrityMode integrityMode(String value) {
        if (INTEGRITY_REPAIR.equals(value)) {
            return IntegrityMode.REPAIR;
        }
        if (INTEGRITY_FAIL.equals(value)) {
            return IntegrityMode.FAIL;
        }
        if (INTEGRITY_IGNORE.equals(value)) {
            return IntegrityMode.IGNORE;
        }
        throw new StoreInitializationFailedException(String.format(
                "Invalid %s '%s'; accepted values are repair, fail and ignore", INTEGRITY_PROPERTY_NAME, value));
    }

    private RuleViolationFileNameStrategy configureFileNameStrategy(Properties properties) {
        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_DEFAULT);
        if (strategyWasProvidedToConstructor) {
            if (properties.getProperty(FILE_NAMES_PROPERTY_NAME) != null) {
                throw new StoreInitializationFailedException(String.format(
                        "%s cannot be configured for a store constructed with a RuleViolationFileNameStrategy", FILE_NAMES_PROPERTY_NAME));
            }
            fileNamesAreDerived = true;
            return constructorStrategy;
        }
        if (FILE_NAMES_RANDOM.equals(configured)) {
            fileNamesAreDerived = false;
            return ignored -> UUID.randomUUID().toString();
        }
        if (FILE_NAMES_DESCRIPTION.equals(configured)) {
            fileNamesAreDerived = true;
            return new DescriptionRuleViolationFileNameStrategy();
        }
        try {
            Class<?> strategyClass = Class.forName(configured);
            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyClass)) {
                throw new IllegalArgumentException("does not implement RuleViolationFileNameStrategy");
            }
            fileNamesAreDerived = true;
            return (RuleViolationFileNameStrategy) strategyClass.getConstructor().newInstance();
        } catch (Exception e) {
            throw new StoreInitializationFailedException(String.format(
                    "Could not instantiate RuleViolationFileNameStrategy configured by %s='%s'; it must be a class with a public no-argument constructor",
                    FILE_NAMES_PROPERTY_NAME, configured), e);
        }
    }

    @Override
    public boolean contains(ArchRule rule) {
        synchronized (storedRules) {
            return storedRules.containsKey(rule.getDescription());
        }
    }

    @Override
    public void save(ArchRule rule, List<String> violations) {
        synchronized (storedRules) {
            log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
            if (!storeUpdateAllowed) {
                throw new StoreUpdateFailedException(String.format(
                        "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
            }

            String description = rule.getDescription();
            String existingFileName = storedRules.getProperty(description);
            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
                if (existingFileName != null) {
                    validateSaveTarget(existingFileName, existingFileName);
                }
                forgetResolvedRule(description, existingFileName);
                return;
            }

            String fileName = existingFileName != null ? existingFileName : createRuleFileName(description, false);
            Path target = validateSaveTarget(fileName, existingFileName);
            boolean targetWasAbsent = !Files.exists(target, NOFOLLOW_LINKS);
            write(violations, target);

            if (existingFileName == null) {
                storedRules.put(description, fileName);
                try {
                    storedRules.sync();
                } catch (RuntimeException e) {
                    if (targetWasAbsent) {
                        deleteQuietly(target);
                    }
                    storedRules.remove(description);
                    throw e;
                }
            }
        }
    }

    private void forgetResolvedRule(String description, String existingFileName) {
        if (existingFileName == null) {
            return;
        }
        if (!isSharedFile(description, existingFileName)) {
            try {
                deleteNamedFile(existingFileName);
            } catch (IOException e) {
                throw new StoreUpdateFailedException(e);
            }
        }
        storedRules.remove(description);
        storedRules.sync();
    }

    private boolean isSharedFile(String description, String fileName) {
        Path path = pathForName(fileName);
        for (Map.Entry<String, String> entry : storedRules.entries().entrySet()) {
            if (entry.getKey().equals(ensureUnixLineBreaks(description))) {
                continue;
            }
            if (entry.getValue().equals(fileName)) {
                return true;
            }
            Path other = pathForName(entry.getValue());
            if (path != null && other != null && sameFile(path, other)) {
                return true;
            }
        }
        return false;
    }

    private Path validateSaveTarget(String fileName, String owningFileName) {
        Path target = pathForName(fileName);
        if (target == null) {
            throw new StoreUpdateFailedException(String.format("Invalid rule violation file name '%s'", fileName));
        }
        Path index = storedRulesFile.toPath().toAbsolutePath().normalize();
        boolean isIndex = target.toAbsolutePath().normalize().equals(index);
        if (!isIndex && Files.exists(target, NOFOLLOW_LINKS)) {
            isIndex = sameFile(target, storedRulesFile.toPath());
        }
        if (isIndex) {
            throw new StoreUpdateFailedException(String.format(
                    "Rule violation file name '%s' leads to the stored rules index", fileName));
        }
        boolean isOwnName = owningFileName != null && owningFileName.equals(fileName);
        if (!isOwnName && Files.exists(target, NOFOLLOW_LINKS)) {
            throw new StoreUpdateFailedException(String.format(
                    "Rule violation file name '%s' names an existing file not recorded by its rule", fileName));
        }
        return target;
    }

    private String createRuleFileName(String description, boolean duringInitialization) {
        String result;
        try {
            result = ruleViolationFileNameStrategy.createRuleFileName(description);
        } catch (RuntimeException e) {
            if (duringInitialization) {
                throw new StoreInitializationFailedException("Could not derive a rule violation file name", e);
            }
            throw e;
        }
        if (result == null || result.isEmpty()) {
            RuntimeException exception = duringInitialization
                    ? new StoreInitializationFailedException("RuleViolationFileNameStrategy returned no file name")
                    : new StoreUpdateFailedException("RuleViolationFileNameStrategy returned no file name");
            throw exception;
        }
        return result;
    }

    private void write(List<String> violations, Path ruleDetails) {
        StringBuilder builder = new StringBuilder();
        for (String violation : violations) {
            builder.append(escape(violation)).append("\n");
        }
        try {
            Files.write(ruleDetails, builder.toString().getBytes(UTF_8),
                    StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
        } catch (IOException e) {
            throw new StoreUpdateFailedException(e);
        }
    }

    private String escape(String violation) {
        return violation.replace("\r", "\\\r").replace("\n", "\\\n");
    }

    private String unescape(String violation) {
        return violation.replace("\\\n", "\n").replace("\\\u0000", "\r");
    }

    @Override
    public List<String> getViolations(ArchRule rule) {
        synchronized (storedRules) {
            String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
            List<String> result = readLines(ruleDetailsFileName);
            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
            return result;
        }
    }

    private List<String> readLines(String ruleDetailsFileName) {
        String violationsText = readStoreFile(ruleDetailsFileName);
        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
                .map(this::unescape)
                .collect(toList());
    }

    private String readStoreFile(String fileName) {
        Path path = pathForName(fileName);
        if (path == null) {
            throw new StoreReadException(new IOException("Invalid stored rule violation file name: " + fileName));
        }
        try {
            String result = new String(toByteArray(path.toFile()), UTF_8);
            return normalizeStoredText(result);
        } catch (IOException e) {
            throw new StoreReadException(e);
        }
    }

    private IntegrityAnalysis analyzeIntegrity() {
        List<IntegrityEntry> entries = new ArrayList<>();
        for (Map.Entry<String, String> entry : storedRules.entries().entrySet()) {
            String derivedName = fileNamesAreDerived
                    ? createRuleFileName(entry.getKey(), true)
                    : entry.getValue();
            entries.add(new IntegrityEntry(entry.getKey(), entry.getValue(), derivedName));
        }
        entries.sort(Comparator.comparing(e -> e.description));

        Map<String, List<IntegrityEntry>> collisionGroups = new HashMap<>();
        for (IntegrityEntry entry : entries) {
            collisionGroups.computeIfAbsent(entry.derivedName, ignored -> new ArrayList<>()).add(entry);
            entry.path = pathForName(entry.fileName);
            entry.broken = entry.path == null || !Files.isRegularFile(entry.path);
            if (!entry.broken) {
                try {
                    entry.resolved = isResolved(entry.path);
                } catch (RuntimeException e) {
                    entry.broken = true;
                }
            }
            entry.misplaced = !entry.fileName.equals(entry.derivedName);
        }
        for (List<IntegrityEntry> group : collisionGroups.values()) {
            if (group.size() > 1) {
                for (IntegrityEntry entry : group) {
                    entry.colliding = true;
                }
            }
        }

        Map<String, List<IntegrityEntry>> nameGroups = new HashMap<>();
        for (IntegrityEntry entry : entries) {
            nameGroups.computeIfAbsent(entry.fileName, ignored -> new ArrayList<>()).add(entry);
        }
        for (List<IntegrityEntry> group : nameGroups.values()) {
            if (group.size() > 1) {
                for (IntegrityEntry entry : group) {
                    entry.shared = true;
                }
            }
        }
        for (int i = 0; i < entries.size(); i++) {
            for (int j = i + 1; j < entries.size(); j++) {
                IntegrityEntry first = entries.get(i);
                IntegrityEntry second = entries.get(j);
                if (!first.broken && !second.broken && sameFile(first.path, second.path)) {
                    first.shared = true;
                    second.shared = true;
                }
            }
        }

        for (IntegrityEntry entry : entries) {
            if (entry.misplaced) {
                entry.occupied = isOccupied(entry, entries);
            }
        }
        return new IntegrityAnalysis(entries, findUnownedFiles(entries));
    }

    private boolean isResolved(Path path) {
        String content;
        try {
            content = normalizeStoredText(new String(Files.readAllBytes(path), UTF_8));
        } catch (IOException e) {
            throw new StoreReadException(e);
        }
        return content.isEmpty() || ONLY_LINE_BREAKS_PATTERN.matcher(content).matches() || readLines(path).isEmpty();
    }

    private List<String> readLines(Path path) {
        try {
            String text = normalizeStoredText(new String(Files.readAllBytes(path), UTF_8));
            return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(text)
                    .map(this::unescape)
                    .collect(toList());
        } catch (IOException e) {
            throw new StoreReadException(e);
        }
    }

    private boolean isOccupied(IntegrityEntry entry, List<IntegrityEntry> entries) {
        Path derivedPath = pathForName(entry.derivedName);
        if (derivedPath == null) {
            return true;
        }
        for (IntegrityEntry other : entries) {
            if (other != entry && other.fileName.equals(entry.derivedName)) {
                return true;
            }
        }
        return Files.exists(derivedPath, NOFOLLOW_LINKS);
    }

    private List<String> findUnownedFiles(List<IntegrityEntry> entries) {
        List<String> result = new ArrayList<>();
        Path folder = storeFolder.toPath();
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(folder)) {
            for (Path child : stream) {
                if (child.getFileName().toString().equals(STORED_RULES_FILE_NAME)
                        || !Files.isRegularFile(child, NOFOLLOW_LINKS)) {
                    continue;
                }
                boolean owned = false;
                for (IntegrityEntry entry : entries) {
                    if (!entry.broken && sameFile(child, entry.path)) {
                        owned = true;
                        break;
                    }
                }
                if (!owned) {
                    result.add(child.getFileName().toString());
                }
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
        Collections.sort(result);
        return result;
    }

    private void repairIntegrity(IntegrityAnalysis analysis) {
        boolean indexChanged = false;
        for (IntegrityEntry entry : analysis.entries) {
            if (entry.shared) {
                continue;
            }
            if (entry.broken) {
                storedRules.remove(entry.description);
                indexChanged = true;
            } else if (entry.resolved) {
                try {
                    deleteNamedFile(entry.fileName);
                } catch (IOException e) {
                    throw new StoreInitializationFailedException("Could not delete resolved rule violation file '" + entry.fileName + "'", e);
                }
                storedRules.remove(entry.description);
                indexChanged = true;
            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
                try {
                    moveNamedFile(entry.fileName, entry.derivedName);
                } catch (IOException e) {
                    throw new StoreInitializationFailedException(String.format(
                            "Could not move rule violation file '%s' to '%s'", entry.fileName, entry.derivedName), e);
                }
                storedRules.put(entry.description, entry.derivedName);
                indexChanged = true;
            }
        }
        if (indexChanged) {
            storedRules.sync();
        }
    }

    private void moveNamedFile(String sourceName, String destinationName) throws IOException {
        Path source = pathForName(sourceName);
        Path destination = pathForName(destinationName);
        if (source == null || destination == null) {
            throw new IOException("Invalid source or destination path");
        }
        if (Files.isSymbolicLink(source)) {
            Path target = source.toRealPath();
            moveAtomicallyWhenPossible(target, destination);
            Files.deleteIfExists(source);
        } else {
            moveAtomicallyWhenPossible(source, destination);
        }
    }

    private void moveAtomicallyWhenPossible(Path source, Path destination) throws IOException {
        try {
            Files.move(source, destination, StandardCopyOption.ATOMIC_MOVE);
        } catch (java.nio.file.AtomicMoveNotSupportedException e) {
            Files.move(source, destination);
        }
    }

    private void deleteNamedFile(String fileName) throws IOException {
        Path path = pathForName(fileName);
        if (path == null) {
            return;
        }
        if (Files.isSymbolicLink(path)) {
            Path target = null;
            try {
                target = path.toRealPath();
            } catch (IOException ignored) {
                // A dangling link has no target to remove, but the link itself is removable.
            }
            if (target != null && !target.equals(path)) {
                Files.delete(target);
            }
            Files.deleteIfExists(path);
        } else if (Files.exists(path, NOFOLLOW_LINKS)) {
            Files.delete(path);
        }
    }

    private void deleteQuietly(Path path) {
        try {
            Files.deleteIfExists(path);
        } catch (IOException ignored) {
            // The original update exception is more useful to the caller.
        }
    }

    private Path pathForName(String name) {
        if (name == null || name.isEmpty()) {
            return null;
        }
        try {
            Path component = Paths.get(name);
            if (component.isAbsolute() || component.getNameCount() != 1
                    || ".".equals(component.toString()) || "..".equals(component.toString())) {
                return null;
            }
            Path folder = storeFolder.toPath().toAbsolutePath().normalize();
            Path result = folder.resolve(component);
            return result.getParent().equals(folder) ? result : null;
        } catch (InvalidPathException e) {
            return null;
        }
    }

    private boolean sameFile(Path first, Path second) {
        try {
            return Files.isSameFile(first, second);
        } catch (IOException e) {
            return false;
        }
    }

    private String normalizeStoredText(String text) {
        StringBuilder result = new StringBuilder(text.length());
        for (int i = 0; i < text.length(); i++) {
            char current = text.charAt(i);
            if (current == '\\' && i + 1 < text.length() && text.charAt(i + 1) == '\r') {
                // Protect a carriage return belonging to a violation from CRLF normalization.
                result.append('\\').append('\u0000');
                i++;
            } else if (current == '\r' && i + 1 < text.length() && text.charAt(i + 1) == '\n') {
                result.append('\n');
                i++;
            } else {
                result.append(current);
            }
        }
        return result.toString();
    }

